// CoLife browser prototype. All Agent execution is a deterministic simulation.
const TODAY='2026-10-08', KEY='colife-prototype-v1';
const pages=[['today','◫','今日工作台'],['goals','◎','目标空间'],['learning','▤','学习中心'],['tasks','▦','任务与日程'],['life','♧','习惯与生活'],['agents','✳','Agent 协作'],['review','◷','复盘与洞察']];
const agents=[{id:'coordinator',name:'协调 Agent',en:'ORCHESTRATOR',icon:'✳',color:'',desc:'理解你的目标，分派任务，汇总伙伴的产出。',detail:'分派与汇总 · 计划需由你确认'},{id:'learning',name:'学习 Agent',en:'LEARNING COMPANION',icon:'▤',color:'purple',desc:'设计学习路线，通过测验发现薄弱点并给出复习建议。',detail:'学习路线 · 测验反馈 · 复习建议'},{id:'planner',name:'计划 Agent',en:'SCHEDULE PLANNER',icon:'▦',color:'blue',desc:'将目标拆成每日任务，让学习安排适应你的可用时间。',detail:'任务拆解 · 日程安排 · 冲突处理'},{id:'life',name:'生活 Agent',en:'LIFE BALANCER',icon:'♧',color:'orange',desc:'关注习惯与精力，为计划补充真实的生活约束。',detail:'习惯记录 · 精力状态 · 时间约束'},{id:'review',name:'复盘 Agent',en:'REFLECTION PARTNER',icon:'◷',color:'gray',desc:'结合执行记录与学习反馈，帮助你找到下一步的方向。',detail:'执行分析 · 薄弱点回顾 · 调整建议'}];
const seed=()=>({goals:[{id:'g1',title:'两周掌握 React 核心能力',type:'学习',deadline:'2026-10-22',minutes:120,criteria:'完成一个 React 项目并记录技术总结',context:'每晚两小时，周三运动；React Hooks 比较薄弱。',status:'进行中'},{id:'g2',title:'让阅读成为日常',type:'生活',deadline:'2026-10-31',minutes:20,criteria:'每周阅读 5 天，记录 3 条读书笔记',context:'睡前留出 20 分钟。',status:'进行中'}],tasks:[{id:'t1',goal:'g1',title:'理解 React Hooks 与闭包',date:TODAY,minutes:45,status:'doing',priority:'高',source:'学习 Agent',note:'先理解 useState 与 useEffect，再用一个计数器验证闭包问题。'},{id:'t2',goal:'g1',title:'实现一个自定义 useFetch',date:TODAY,minutes:45,status:'todo',priority:'中',source:'计划 Agent',note:'覆盖加载、成功与异常三种状态。'},{id:'t3',goal:'g1',title:'梳理 JavaScript 事件循环',date:TODAY,minutes:30,status:'done',priority:'中',source:'学习 Agent',note:'用微任务与宏任务的例子说明执行顺序。'},{id:'t4',goal:'g2',title:'阅读《原子习惯》并记录心得',date:TODAY,minutes:20,status:'todo',priority:'低',source:'生活 Agent',note:'示例阅读任务，可以替换为你的书目。'},{id:'t5',goal:'g1',title:'练习组件状态管理',date:'2026-10-09',minutes:50,status:'todo',priority:'中',source:'学习 Agent',note:'尝试 Context 与 reducer。'},{id:'t6',goal:'g1',title:'完成一次项目成果复盘',date:'2026-10-11',minutes:60,status:'todo',priority:'高',source:'计划 Agent',note:'从项目目标、架构与难点三个角度讲解。'}],habits:[{id:'h1',name:'每天阅读',target:'20 分钟，让知识慢慢积累',icon:'▤'},{id:'h2',name:'规律运动',target:'30 分钟，给身体一点能量',icon:'♧'},{id:'h3',name:'早点休息',target:'23:00 前准备入睡',icon:'☾'}],checks:{},energy:'一般',notes:[],focusSeconds:0,enabled:Object.fromEntries(agents.map(a=>[a.id,true])),runs:[],quiz:null,review:null,activities:[]});
let storageWarning=false,state;
try{const data=JSON.parse(localStorage.getItem(KEY));state=data&&Array.isArray(data.tasks)&&Array.isArray(data.goals)&&Array.isArray(data.habits)&&data.enabled?{...seed(),...data}:seed()}catch{state=seed();storageWarning=true}
// Update built-in sample copy without clearing personal records or progress.
if(state.exampleCopyVersion!==2){
 const defaults=seed(),g=state.goals.find(g=>g.id==='g1'),sample=defaults.goals.find(g=>g.id==='g1');
 if(g){
  const previousTitle=g.title,previousCriteria=g.criteria;
  g.title=sample.title;g.criteria=sample.criteria;
  const updateText=value=>{if(typeof value!=='string')return value;let text=value;if(previousTitle)text=text.replaceAll(previousTitle,sample.title);if(previousCriteria)text=text.replaceAll(previousCriteria,sample.criteria);return text};
  state.tasks.filter(t=>t.goal==='g1').forEach(t=>{t.title=updateText(t.title);t.note=updateText(t.note)});
  state.runs.filter(r=>r.goal==='g1').forEach(r=>{r.title=updateText(r.title);r.summary=updateText(r.summary);(r.proposal||[]).forEach(t=>{t.title=updateText(t.title);t.note=updateText(t.note)})});
  state.activities.forEach(a=>a.text=updateText(a.text));
 }
 const task=state.tasks.find(t=>t.id==='t6');
 if(task){const sampleTask=defaults.tasks.find(t=>t.id==='t6');task.title=sampleTask.title;task.note=sampleTask.note}
 state.exampleCopyVersion=2;
}
let page=pages.some(p=>p[0]===location.hash.slice(1))?location.hash.slice(1):'today',taskView='board',goalFilter='全部',taskFilter='all',weekOffset=0,reviewPeriod='today',runTimer=null,activeRun=null,modalDirty=false,focusTimer=null,focusElapsed=0,focusRunning=false,lastFocusTick=0,lastFocused=null,toastTimer;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const addDays=(d,n)=>{const t=new Date(d+'T12:00:00');t.setDate(t.getDate()+n);return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`};
const pretty=d=>`${Number(d.slice(5,7))}月${Number(d.slice(8))}日`;
const goalProgress=g=>{const ts=state.tasks.filter(t=>t.goal===g.id);return ts.length?Math.round(ts.filter(t=>t.status==='done').length/ts.length*100):0};
const todayTasks=()=>state.tasks.filter(t=>t.date===TODAY),doneTasks=()=>todayTasks().filter(t=>t.status==='done'),checked=h=>!!state.checks[`${TODAY}:${h.id}`];
const goalName=gid=>state.goals.find(g=>g.id===gid)?.title||'个人任务';
const statusName={todo:'待办',doing:'进行中',done:'已完成'};
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('浏览器存储不可用，本次操作仅保留在会话中。')}}
function log(text){state.activities.unshift({text,at:new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})});state.activities=state.activities.slice(0,8)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function heading(eyebrow,title,description,action=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function stat(label,value,unit,foot){return `<div class="stat"><div class="stat-label">${label}<span>↗</span></div><div class="stat-number">${value}<em>${unit}</em></div><small>${foot}</small></div>`}
function progress(p){return `<div class="progress-track"><i style="width:${p}%"></i></div>`}
function empty(title,description=''){return `<div class="empty"><span>◎</span>${title}<p>${description}</p></div>`}
function taskRow(t){return `<div class="task-row"><button class="check ${t.status==='done'?'checked':''}" data-action="toggle-task" data-id="${t.id}" aria-label="${t.status==='done'?'恢复':'完成'} ${esc(t.title)}">${t.status==='done'?'✓':''}</button><div class="task-body"><button class="task-title ${t.status==='done'?'done':''}" data-action="task-detail" data-id="${t.id}">${esc(t.title)}</button><div class="task-meta"><span>${esc(goalName(t.goal))}</span><span>· ${t.minutes} 分钟</span></div></div><span class="tag ${t.status==='doing'?'orange':t.status==='done'?'gray':''}">${statusName[t.status]}</span></div>`}
function habitsList(){return state.habits.map(h=>`<div class="habit-row"><span class="habit-icon">${h.icon}</span><div class="task-body"><b>${esc(h.name)}</b><small>${esc(h.target)}</small></div><button class="pill ${checked(h)?'done':''}" data-action="habit-check" data-id="${h.id}">${checked(h)?'✓ 已打卡':'打卡'}</button></div>`).join('')}
function render(){
 $('#crumb').textContent=pages.find(p=>p[0]===page)[2];
 $('#nav').innerHTML=pages.map(([key,icon,name])=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''} aria-label="${name}" title="${name}"><span class="nav-icon">${icon}</span><span>${name}</span>${key==='agents'?'<span class="count">5</span>':''}</a>`).join('');
 const views={today:todayPage,goals:goalsPage,learning:learningPage,tasks:tasksPage,life:lifePage,agents:agentsPage,review:reviewPage};
 $('#main').innerHTML=views[page]();renderRail();
}
function renderRail(){const last=state.activities.length?state.activities.slice(0,3):[{text:'计划 Agent 安排了今天的学习任务',at:'示例记录'},{text:'学习 Agent 推荐先巩固 React Hooks',at:'示例记录'},{text:'你的伙伴已就绪，随时开始协作',at:'示例记录'}];$('#copilot').innerHTML=`<div class="copilot-head"><h2>你的协作伙伴</h2><span class="live">● ${Object.values(state.enabled).filter(Boolean).length} 位就绪</span></div><p>各有所长，朝着同一个方向。</p>${agents.map(a=>`<div class="agent-item"><span class="agent-avatar ${a.color}">${a.icon}</span><div><b>${a.name}</b><small>${state.enabled[a.id]?a.detail:'已暂停参与协作'}</small></div><span class="online" style="background:${state.enabled[a.id]?'#80a573':'#c5c9c0'}"></span></div>`).join('')}<div class="agent-message"><b>✧ 一个小小的建议</b><p>${state.energy==='疲惫'?'今天有点疲惫？可以保留重点学习，把一个未完成任务安排到明天。':'先完成 React Hooks，再动手写 useFetch，知识会在实践中连接起来。'}</p><button class="btn subtle" data-action="${state.energy==='疲惫'?'reschedule':'start-focus'}">${state.energy==='疲惫'?'查看调整建议 ↗':'开始一段专注时间 ↗'}</button></div><div class="rail-title">最近的协作</div>${last.map(a=>`<div class="activity">${esc(a.text)}<small>${esc(a.at)}</small></div>`).join('')}<button class="text-button" data-action="navigate" data-page="agents">查看协作中心 →</button><div class="rail-footer">原型基准日期 · 2026.10.08<br>Agent 结果为模拟生成，操作保存在本地。</div>`}
function todayPage(){const ts=todayTasks(),ds=doneTasks(),hc=state.habits.filter(checked).length;return heading('THURSDAY, OCTOBER 08','下午好，林同学 <span>☀</span>','成长不必匆忙，让今天的每一步都有方向。',`<button class="btn" data-action="new-goal">＋ 新建目标</button>`)+`<section class="hero"><div><div class="eyebrow">A LITTLE PROGRESS, EVERY DAY</div><h2>你的目标，有一群伙伴同行。</h2><p>学习、计划、生活与复盘，五位 Agent 协同工作。<br>你专注当下，我们一起照看前进的方向。</p><small>✳ ${Object.values(state.enabled).filter(Boolean).length} 位协作伙伴就绪 · ${state.goals.filter(g=>g.status==='进行中').length} 个目标正在进行</small></div><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="orbit two"></div><div class="orbit three">✳</div><span class="planet a">▤</span><span class="planet b">♧</span><span class="planet c">◎</span></div></section><div class="stats">${stat('今日任务',`${ds.length}<em>/ ${ts.length}</em>`,'','一步一步，靠近目标')}${stat('累计专注',Math.floor(state.focusSeconds/60),'分钟','从一段不被打扰的时间开始')}${stat('习惯达成',`${hc}<em>/ ${state.habits.length}</em>`,'',hc?'今天也在照顾自己':'小习惯，带来大改变')}${stat('进行中目标',state.goals.filter(g=>g.status==='进行中').length,'个','保持热爱，也保持节奏')}</div><div class="grid-two"><section class="card"><div class="section-head"><h2>今天，专注这些 <small>重要的事，留出专属时间。</small></h2><button class="text-button" data-action="navigate" data-page="tasks">全部任务 →</button></div>${ts.map(taskRow).join('')||empty('今天还没有任务','试试让伙伴为你制定一份计划。')}<div class="inline-info">◷ 今日计划 ${ts.reduce((s,t)=>s+t.minutes,0)} 分钟 · 留一点空白，给生活。</div></section><section class="card"><div class="section-head"><h2>给生活一点仪式感</h2><button class="text-button" data-action="navigate" data-page="life">↗</button></div>${habitsList()}<div class="energy"><span>今天的精力如何？</span><select id="energy" aria-label="今日精力">${['充沛','一般','疲惫'].map(x=>`<option ${state.energy===x?'selected':''}>${x}</option>`).join('')}</select></div></section></div><section class="card"><div class="section-head"><h2>正在靠近的目标</h2><button class="text-button" data-action="navigate" data-page="goals">目标空间 →</button></div>${state.goals.slice(0,3).map(g=>`<div class="goal-mini"><div class="section-head"><button class="task-title" data-action="goal-detail" data-id="${g.id}">${esc(g.title)}</button><span class="tiny muted">${goalProgress(g)}%</span></div>${progress(goalProgress(g))}<small>${esc(g.type)}目标 · 截止 ${pretty(g.deadline)} · ${esc(g.status)}</small></div>`).join('')}</section><div class="footer-note">不必一次做好所有事，今天也值得被记录。</div>`}
function goalsPage(){const gs=state.goals.filter(g=>goalFilter==='全部'||g.status===goalFilter);return heading('GOALS & MILESTONES','每一个目标，都有下一步','把愿望变成路线，让伙伴陪你走过每个里程碑。','<button class="btn" data-action="new-goal">＋ 新建目标</button>')+`<div class="tabs">${['全部','进行中','草稿','待确认'].map(f=>`<button class="tab ${goalFilter===f?'active':''}" data-action="goal-filter" data-value="${f}">${f}</button>`).join('')}</div><div class="cards-grid">${gs.map(g=>`<article class="card goal-card"><div class="bottom"><span class="tag ${g.type==='生活'?'orange':''}">${esc(g.type)}目标</span><span class="tiny muted">${esc(g.status)}</span></div><h2>${esc(g.title)}</h2><p>${esc(g.criteria||'和伙伴一起定义你的验收标准。')}</p>${progress(goalProgress(g))}<div class="bottom tiny"><span class="muted">${goalProgress(g)}% 完成 · ${pretty(g.deadline)}截止</span><button class="text-button" data-action="goal-detail" data-id="${g.id}">查看路线 ↗</button></div></article>`).join('')}<button class="new-card" data-action="new-goal"><span>＋</span><b>开始一个新目标</b><small>一个想法，就是起点。</small></button></div>`}
function learningPage(){const g=state.goals.find(g=>g.type==='学习'),notes=state.notes;return heading('LEARN WITH INTENTION','让知识，慢慢连成一片','从学习路线到自我检验，每一步都有反馈。','<button class="btn" data-action="quiz">✧ 开始知识测验</button>')+`<div class="grid-two"><section class="card"><div class="section-head"><h2>当前学习路线<small>${esc(g?.title||'先创建一个学习目标')}</small></h2><span class="tag purple">学习 Agent</span></div>${[{title:'JavaScript 基础与运行机制',desc:'事件循环、闭包与异步，搭建理解的底座。',tag:'基础阶段'},{title:'React 核心与 Hooks 实践',desc:'理解状态与副作用，用自定义 Hook 连接知识。',tag:'当前重点'},{title:'工程实践与成果总结',desc:'用项目验证理解，再把技术决策讲清楚。',tag:'下一个里程碑'}].map((s,i)=>`<div class="route-step ${i===1?'current':''}"><span class="step-index">${i+1}</span><div><h3>${s.title}</h3><p>${s.desc}</p><span class="tag ${i===1?'purple':'gray'}">${s.tag}</span></div></div>`).join('')}<div class="inline-info">示例路线 · 正式版本将根据目标与测验动态生成。</div></section><section class="card"><div class="section-head"><h2>知道自己，还差哪一步</h2></div><div class="eyebrow">KNOWLEDGE CHECK</div><h2 style="font-size:24px;margin:12px 0">${state.quiz?`${state.quiz.score} / 3`:'3 道小题'}</h2><p class="tiny">${state.quiz?'最近一次 React 测验得分。每一次反馈，都是下一次进步的起点。':'用三道 React 问题检验理解，发现需要复习的知识点。'}</p><div class="insight"><h3>${state.quiz?(state.quiz.score===3?'理解得不错，继续实践。':'建议巩固 Hooks 与副作用'):'把“看懂了”变成“会用了”'}</h3><p>${state.quiz?'你可以再次测验，也可以把复习建议加入任务。':'测验反馈会连接到你的任务与复盘。'}</p></div><button class="btn secondary" style="width:100%;margin-top:18px" data-action="quiz">${state.quiz?'再次测验':'开始测验'} →</button>${state.quiz&&state.quiz.score<3?'<button class="text-button" data-action="quiz-task" style="margin-top:10px">将薄弱点加入复习任务 →</button>':''}</section></div><section class="card"><div class="section-head"><h2>学习资料小站</h2><span class="tiny muted">示例学习卡片</span></div><div class="resources">${[['▤','React Hooks 速记','状态、依赖与闭包','hooks'],['⌘','动手写一个 useFetch','用实践连接知识','fetch'],['◷','事件循环图解','理解异步执行顺序','loop']].map(r=>`<button class="resource" data-action="resource" data-id="${r[3]}"><span>${r[0]}</span><b>${r[1]}</b><small>${r[2]} ↗</small></button>`).join('')}</div></section><section class="card"><div class="section-head"><h2>留下自己的理解<small>知识经过表达，才更容易被记住。</small></h2><button class="btn secondary small" data-action="new-note">＋ 写一条笔记</button></div>${notes.length?notes.map(n=>`<div class="note"><div class="bottom"><b>${esc(n.title)}</b><button class="text-button" data-action="edit-note" data-id="${n.id}">编辑</button></div>${esc(n.body)}</div>`).join(''):empty('这里等待你的第一条笔记','把今天理解的一点知识，用自己的话写下来。')}</section>`}
function tasksPage(){const ts=state.tasks.filter(t=>taskFilter==='all'||t.goal===taskFilter);let body;if(taskView==='board'){body=`<div class="kanban">${['todo','doing','done'].map(s=>`<div class="column"><div class="column-head"><b><span class="dot ${s==='doing'?'orange':''}"></span>${statusName[s]}</b><span>${ts.filter(t=>t.status===s).length}</span></div>${ts.filter(t=>t.status===s).map(t=>`<article class="task-card"><span class="tag ${t.priority==='高'?'orange':'gray'}">${t.priority}优先级</span><h3><button class="task-title" data-action="task-detail" data-id="${t.id}">${esc(t.title)}</button></h3><p>${esc(goalName(t.goal))}</p><div class="bottom"><span class="muted">${pretty(t.date)} · ${t.minutes}m</span><select data-task="${t.id}" aria-label="${esc(t.title)}的状态">${['todo','doing','done'].map(k=>`<option value="${k}" ${k===s?'selected':''}>${statusName[k]}</option>`).join('')}</select></div></article>`).join('')||'<div class="empty">暂时没有任务</div>'}</div>`).join('')}</div>`}else{const start=addDays('2026-10-05',weekOffset*7);body=`<section class="card"><div class="section-head"><button class="text-button" data-action="week" data-value="-1">← 上一周</button><b class="tiny">${pretty(start)} — ${pretty(addDays(start,6))}</b><button class="text-button" data-action="week" data-value="1">下一周 →</button></div><div class="week-calendar">${Array.from({length:7},(_,i)=>{const d=addDays(start,i);return `<div class="day-cell ${d===TODAY?'today':''}"><div class="day-label">${['周一','周二','周三','周四','周五','周六','周日'][i]}<b>${Number(d.slice(8))}</b></div>${ts.filter(t=>t.date===d).map(t=>`<button class="calendar-task ${t.status==='done'?'done':''}" data-action="task-detail" data-id="${t.id}">${esc(t.title)}<small>${t.minutes} 分钟 · ${statusName[t.status]}</small></button>`).join('')}</div>`}).join('')}</div></section>`}return heading('MAKE ROOM FOR WHAT MATTERS','为重要的事，留出时间','计划是一个起点，也可以随着生活灵活调整。','<button class="btn" data-action="new-task">＋ 添加任务</button>')+`<div class="toolbar"><div class="tabs"><button class="tab ${taskView==='board'?'active':''}" data-action="task-view" data-value="board">▦ 任务看板</button><button class="tab ${taskView==='calendar'?'active':''}" data-action="task-view" data-value="calendar">▦ 周日历</button></div><div style="display:flex;gap:8px"><select id="task-filter" aria-label="按目标筛选"><option value="all">所有目标</option>${state.goals.map(g=>`<option value="${g.id}" ${taskFilter===g.id?'selected':''}>${esc(g.title)}</option>`).join('')}</select><button class="btn secondary small" data-action="reschedule">✧ 重新排期</button></div></div>${body}<div class="footer-note">切换任务状态，工作台与目标进度会同步更新。</div>`}
function lifePage(){const hc=state.habits.filter(checked).length;return heading('A BALANCED LIFE','照顾生活，也是成长的一部分','小小的习惯，日复一日，构成你想要的生活。','<button class="btn" data-action="new-habit">＋ 添加习惯</button>')+`<div class="stats">${stat('今日打卡',hc,'项','每一步都值得被看见')}${stat('习惯总数',state.habits.length,'项','为生活留出一点仪式感')}${stat('今日达成',Math.round(hc/Math.max(1,state.habits.length)*100),'%','按当天真实记录计算')}${stat('精力状态',state.energy,'','尊重自己的节奏')}</div><div class="habit-cards">${state.habits.map(h=>`<section class="card habit-card"><div class="habit-icon">${h.icon}</div><h2>${esc(h.name)}</h2><p>${esc(h.target)}</p><div class="week-dots">${Array.from({length:7},(_,i)=>{const d=addDays('2026-10-05',i),check=state.checks[`${d}:${h.id}`];return `<div class="week-dot ${check?'active':''}">${['一','二','三','四','五','六','日'][i]}<i>${check?'✓':'·'}</i></div>`}).join('')}</div><p>本周已完成 ${Array.from({length:7},(_,i)=>!!state.checks[`${addDays('2026-10-05',i)}:${h.id}`]).filter(Boolean).length} 次</p><button class="btn ${checked(h)?'secondary':''}" data-action="habit-check" data-id="${h.id}">${checked(h)?'✓ 已打卡 · 点击撤销':'完成今天的打卡'}</button></section>`).join('')}</div><section class="card"><div class="section-head"><h2>今日精力记录</h2><span class="tag orange">生活 Agent</span></div><p class="tiny">你的精力影响计划的负荷。调整建议会先交给你确认。</p><div class="chips" style="margin-top:20px">${['充沛','一般','疲惫'].map(e=>`<button class="btn ${state.energy===e?'':'secondary'}" data-action="energy" data-value="${e}">${e==='充沛'?'☀':e==='一般'?'◐':'☾'} ${e}</button>`).join('')}</div><div class="insight"><h3>${state.energy==='疲惫'?'放慢一点，也是在前进。':'给今天留一点呼吸的空间。'}</h3><p>${state.energy==='疲惫'?'建议保留重点任务，把一个未完成事项移到明天。确认后才会修改日程。':'固定安排与休息时间应该先被保护，再安排学习。你可以查看一份示例调整。'}</p><button class="text-button" style="margin-top:12px" data-action="reschedule">查看日程调整建议 →</button></div></section>`}
function agentsPage(){return heading('BETTER, TOGETHER','五位伙伴，一个共同方向','职责明确、过程可见，让每一次协作都有结果。','<button class="btn" data-action="sample-run">✳ 发起一次协作</button>')+`<div class="inline-info">原型模式 · 这里展示模拟编排与交接摘要，不包含真实模型推理。配置会影响后续模拟运行。</div><div class="agent-cards">${agents.map(a=>`<section class="card agent-card"><div class="section-head"><div class="agent-role"><span class="agent-avatar ${a.color}">${a.icon}</span><div><h3>${a.name}</h3><small>${a.en}</small></div></div><button class="switch ${state.enabled[a.id]?'on':''}" role="switch" aria-checked="${state.enabled[a.id]}" aria-label="启用${a.name}" data-action="agent-toggle" data-id="${a.id}"><span></span></button></div><p>${a.desc}</p><div class="bottom"><span class="tag ${state.enabled[a.id]?'':'gray'}">${state.enabled[a.id]?'已就绪':'已暂停'}</span><button class="text-button" data-action="agent-detail" data-id="${a.id}">角色说明 ↗</button></div></section>`).join('')}</div><section class="card" style="margin-top:22px"><div class="section-head"><h2>协作运行记录<small>记录每次运行的状态与可审阅产出。</small></h2><button class="text-button" data-action="failure-run">模拟失败与重试 ↗</button></div>${state.runs.length?state.runs.slice().reverse().map(r=>`<div class="run-log"><span class="agent-avatar">✳</span><div class="task-body"><b>${esc(r.title)}</b><p>${esc(r.summary||'模拟运行')}</p><small>${esc(r.time)} · ${r.id.slice(0,8)}</small></div><span class="run-state ${r.status==='失败'?'failed':''}">${esc(r.status)}</span><button class="text-button" data-action="run-detail" data-id="${r.id}">查看</button></div>`).join(''):empty('还没有协作记录','从一个新目标开始，或者发起一次示例协作。')}</section>`}
function reviewPage(){const all=state.tasks.filter(t=>reviewPeriod==='week'?t.date>='2026-10-05'&&t.date<='2026-10-11':t.date===TODAY),done=all.filter(t=>t.status==='done');return heading('REFLECT, THEN MOVE FORWARD','回头看，是为了更好地向前','让记录变成反馈，让下一步更适合你。','<button class="btn" data-action="generate-review">✧ 生成复盘</button>')+`<div class="tabs"><button class="tab ${reviewPeriod==='today'?'active':''}" data-action="review-period" data-value="today">今日复盘</button><button class="tab ${reviewPeriod==='week'?'active':''}" data-action="review-period" data-value="week">本周洞察</button></div><div class="stats">${stat('任务完成率',Math.round(done.length/Math.max(1,all.length)*100),'%',`${done.length} / ${all.length} 个任务已完成`)}${stat('累计专注',Math.floor(state.focusSeconds/60),'分钟','来自本地计时记录')}${stat('习惯打卡',Object.keys(state.checks).filter(k=>state.checks[k]&&(reviewPeriod==='today'?k.startsWith(TODAY):k.slice(0,10)>='2026-10-05'&&k.slice(0,10)<='2026-10-11')).length,'次','来自真实打卡记录')}${stat('测验反馈',state.quiz?state.quiz.score:'—',state.quiz?'/ 3':'','最近一次测验')}</div><div class="grid-two"><section class="card"><div class="section-head"><h2>一点一点，积累成变化</h2><span class="tag gray">示例趋势</span></div><p class="tiny">以下柱状图为视觉示例，上方指标来自本地操作。</p><div class="chart">${[45,65,50,80,55,90,70].map((v,i)=>`<div class="bar-group"><div class="bar"><i style="height:${v}%"></i><i class="alt" style="height:${v*0.65+10}%"></i></div><span>${['一','二','三','四','五','六','日'][i]}</span></div>`).join('')}</div><div class="legend"><span><i class="dot"></i> 学习时间</span><span><i class="dot orange"></i> 生活习惯</span></div></section><section class="card"><div class="section-head"><h2>值得被看见的进步</h2><span class="tag">复盘 Agent</span></div><div class="insight"><h3>${done.length?'你完成了 '+done.length+' 个任务':'从完成一个小任务开始'}</h3><p>${done.length?`已完成任务的计划耗时合计 ${done.reduce((s,t)=>s+t.minutes,0)} 分钟。这是计划估值，实际专注时长见上方记录。`:'记录真实执行后，复盘才能提供更有依据的反馈。'}</p></div><div class="insight"><h3>${state.quiz&&state.quiz.score<3?'给薄弱点一点额外时间':'计划也需要弹性'}</h3><p>${state.quiz&&state.quiz.score<3?'最近测验仍有未掌握知识，可以把复习加入下一次安排。':'状态不好时调整负荷，完成后及时记录，让计划跟上真实生活。'}</p></div></section></div><section class="card"><div class="section-head"><h2>你的复盘记录</h2><span class="tiny muted">基于本地记录的模拟总结</span></div>${state.review?`<div class="note"><b>${esc(state.review.title)}</b>\n${esc(state.review.text)}</div><div class="bottom" style="margin-top:18px"><span class="tiny muted">建议：明天用 25 分钟复习薄弱点与整理计划。</span><button class="btn secondary small" data-action="apply-review" ${state.review.applied?'disabled':''}>${state.review.applied?'✓ 已加入明日任务':'应用复盘建议'}</button></div>`:empty('一次停下来，就是新的起点','点击“生成复盘”，回顾真实完成与习惯记录。')}</section>`}

function showModal(title,desc,body,footer=''){lastFocused=document.activeElement;modalDirty=false;$('#modal').innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="close" data-action="close-modal" aria-label="关闭弹窗">×</button></div><p class="modal-desc">${desc}</p>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();setTimeout(()=>$('#modal').querySelector('input,textarea,select,button:not(.close)')?.focus(),20)}
function closeModal(force=false){if(!force&&focusTimer){showFocusLeave();return}if(!force&&modalDirty){if(!confirm('有未保存的内容，确认放弃？'))return}if(activeRun&&activeRun.status==='运行中'){clearInterval(runTimer);runTimer=null;activeRun.status='取消';activeRun.summary='用户关闭了模拟协作';const g=state.goals.find(g=>g.id===activeRun.goal);if(g)g.status='草稿';save();render()}$('#modal').close();modalDirty=false;lastFocused?.focus?.()}
function newGoal(){showModal('从一个目标开始','告诉伙伴你想做什么，以及能为它留出多少时间。',`<form id="goal-form"><label class="field">目标名称<input name="title" required maxlength="60" placeholder="例如：两周内完成 React 学习与项目实践"></label><div class="form-grid"><label class="field">目标类型<select name="type"><option>学习</option><option>生活</option></select></label><label class="field">截止日期<input type="date" name="deadline" value="2026-10-22" min="${TODAY}" required></label></div><label class="field">每日可用时间（分钟）<input type="number" name="minutes" value="120" min="15" max="480" step="1" required></label><label class="field">怎样算完成？<input name="criteria" maxlength="300" placeholder="例如：完成一个项目并整理学习总结"></label><label class="field">背景与时间限制<textarea name="context" maxlength="500" placeholder="例如：每晚两小时；周三要运动；React 比较薄弱。"></textarea></label><div id="form-error" role="alert" class="error"></div><div class="modal-footer"><button type="button" class="btn secondary" data-action="save-draft">保存草稿</button><button class="btn" type="submit">✳ 让伙伴制定计划</button></div></form>`)}
function submitGoal(draft=false){const form=$('#goal-form');if(!form.reportValidity())return;const f=new FormData(form),title=f.get('title').trim(),minutes=Number(f.get('minutes'));if(!title||!Number.isInteger(minutes)||minutes<15||minutes>480||f.get('deadline')<TODAY){$('#form-error').textContent='请填写有效标题、日期与 15–480 的整数分钟。';return}const g={id:id(),title,type:f.get('type'),deadline:f.get('deadline'),minutes,criteria:f.get('criteria').trim(),context:f.get('context').trim(),status:'草稿'};state.goals.push(g);save();modalDirty=false;if(draft){closeModal(true);navigate('goals');toast('目标草稿已保存')}else startRun(g)}
function goalDetail(g){const ts=state.tasks.filter(t=>t.goal===g.id);showModal(esc(g.title),`${esc(g.type)}目标 · ${pretty(g.deadline)}截止 · ${esc(g.status)}`,`<div class="bottom"><span class="tag">${goalProgress(g)}% 已完成</span><span class="tiny muted">每日 ${g.minutes} 分钟</span></div>${progress(goalProgress(g))}<div class="inline-info"><b>验收标准</b><br>${esc(g.criteria||'待你和伙伴一起定义')}<br><br><b>生活与时间约束</b><br>${esc(g.context||'暂无额外限制')}</div><h3>关联任务与路线</h3>${ts.map(taskRow).join('')||empty('目标还没有任务','让伙伴将目标拆解为可执行步骤。')}`,`<button class="btn secondary" data-action="close-modal">关闭</button><button class="btn" data-action="goal-plan" data-id="${g.id}">${ts.length?'再生成一份提案':'生成计划'}</button>`)}
function startRun(g,fail=false){if(activeRun?.status==='运行中'){toast('当前已有协作运行，请等待或关闭后再试。');return}const required=g.type==='学习'?['coordinator','learning','planner']:['coordinator','life','planner'];if(required.some(k=>!state.enabled[k])){toast('请先在协作中心启用协调、计划及对应领域 Agent。');return}const run={id:id(),goal:g.id,title:g.title,time:new Date().toLocaleTimeString('zh-CN'),status:'运行中',summary:'伙伴正在协作',steps:[],proposal:[],applied:false};activeRun=run;state.runs.push(run);g.status='规划中';save();let step=0;const order=['coordinator',g.type==='学习'?'learning':'life',g.type==='学习'?'life':'learning','planner','review'];const messages={coordinator:'已识别目标与验收标准，分派学习与生活子任务。',learning:g.type==='学习'?'将目标拆成理解基础、动手练习、验证成果三个阶段。':'本次生活目标无需额外学习路线。',life:`已读取每日 ${g.minutes} 分钟可用时间与生活约束。`,planner:'已安排三个执行步骤，等待你审阅后加入日程。',review:'已补充验收与复盘检查点，汇总提案。'};function frame(){showModal('伙伴正在一起想办法',`模拟协作 · ${esc(g.title)}`,`<div class="run-progress"><i style="width:${step/5*100}%"></i></div>${order.map((k,i)=>{const a=agents.find(a=>a.id===k),s=run.steps[i];return `<div class="run-log"><span class="agent-avatar ${a.color}">${a.icon}</span><div class="task-body"><b>${a.name}</b><p>${s?esc(s.message):i===step?'正在处理本阶段…':'等待上游产出'}</p></div><span class="run-state ${s?.status==='失败'?'failed':''}">${s?s.status:i===step?'<span class="spin">◌</span> 运行中':'等待'}</span></div>`}).join('')}`)}frame();clearInterval(runTimer);runTimer=setInterval(()=>{const k=order[step],enabled=state.enabled[k];if(fail&&step===3){run.steps.push({agent:k,status:'失败',message:'模拟超时：计划节点未返回产出。已完成的上游摘要保留。'});run.status='失败';run.summary='计划节点模拟超时，可重试';g.status='草稿';clearInterval(runTimer);runTimer=null;save();render();showRun(run);return}run.steps.push({agent:k,status:enabled?'成功':'跳过',message:enabled?messages[k]:'角色已暂停，本阶段跳过。'});step++;save();if(step===5){clearInterval(runTimer);runTimer=null;run.status='待确认';run.summary='协作已完成，计划等待确认';g.status='待确认';const span=Math.max(0,Math.round((new Date(g.deadline+'T12:00:00')-new Date(TODAY+'T12:00:00'))/86400000));const titles=g.type==='学习'?['梳理基础与关键知识','完成一次动手练习','检验理解并复盘']:['建立第一步行动','实践并记录过程','回顾成果与调整习惯'];run.proposal=titles.map((s,i)=>({id:id(),goal:g.id,title:`${g.title} · ${s}`,date:addDays(TODAY,Math.min(i,span)),minutes:Math.max(15,Math.min(60,Math.floor(g.minutes/(span===0?3:1)))),status:'todo',priority:i===0?'高':'中',source:'计划 Agent',note:`模拟计划步骤 ${i+1}。验收：${g.criteria||'完成步骤后记录成果。'}`}));log(`伙伴为“${g.title}”生成了待确认计划`);save();render();showProposal(run)}else frame()},650)}
function showProposal(run){activeRun=run;const g=state.goals.find(g=>g.id===run.goal);showModal('计划准备好了，由你决定','模拟提案 · 确认后才会创建任务。',`<div class="inline-info"><b>${esc(g?.title||run.title)}</b><br>${esc(g?.context||'没有额外限制，建议保留休息时间。')}<br>验收：${esc(g?.criteria||'完成三个步骤并记录成果。')}</div>${run.proposal.map(t=>`<div class="proposal-task"><b>${esc(t.title)}</b><small>${pretty(t.date)} · ${t.minutes} 分钟 · ${t.priority}优先级</small></div>`).join('')}<p class="tiny muted">当前原型按顺序安排步骤，日期不晚于截止日。正式版需要检测完整日程与依赖冲突。</p>`,`<button class="btn secondary" data-action="dismiss-proposal" data-id="${run.id}">暂不应用</button><button class="btn" data-action="apply-proposal" data-id="${run.id}" ${run.applied?'disabled':''}>${run.applied?'✓ 已应用':'确认并加入日程'}</button>`)}
function showRun(r){if(r.status==='待确认'){showProposal(r);return}showModal('这一次，伙伴怎样协作',`${esc(r.title)} · ${esc(r.status)}`,`${r.steps.map(s=>{const a=agents.find(a=>a.id===s.agent);return `<div class="run-log"><span class="agent-avatar ${a.color}">${a.icon}</span><div><b>${a.name} · ${s.status}</b><p>${esc(s.message)}</p></div></div>`}).join('')}<div class="inline-info">${esc(r.summary)}</div>`,`${r.status==='失败'?`<button class="btn" data-action="retry-run" data-id="${r.id}">重试这次协作</button>`:'<button class="btn secondary" data-action="close-modal">关闭</button>'}`)}
function newTask(){showModal('留下一件要做的事','任务会同步出现在工作台与日程。',`<form id="task-form"><label class="field">任务名称<input name="title" maxlength="80" required placeholder="例如：完成一轮 React 练习"></label><label class="field">关联目标<select name="goal"><option value="">个人任务</option>${state.goals.map(g=>`<option value="${g.id}">${esc(g.title)}</option>`).join('')}</select></label><div class="form-grid"><label class="field">安排日期<input type="date" name="date" value="${TODAY}" required></label><label class="field">预计分钟<input type="number" name="minutes" min="1" max="480" value="30" required step="1"></label></div><label class="field">优先级<select name="priority"><option>中</option><option>高</option><option>低</option></select></label><div id="form-error" role="alert" class="error"></div><div class="modal-footer"><button class="btn" type="submit">添加任务</button></div></form>`)}
function taskDetail(t){showModal(esc(t.title),`${esc(goalName(t.goal))} · ${pretty(t.date)}`,`<div class="chips"><span class="tag">${statusName[t.status]}</span><span class="tag orange">${t.priority}优先级</span><span class="tag gray">预计 ${t.minutes} 分钟</span></div><div class="inline-info">${esc(t.note||'先做一个小步骤，再记录你的收获。')}</div><p class="tiny muted">来源：${esc(t.source)}${t.actualSeconds?` · 实际专注 ${Math.floor(t.actualSeconds/60)} 分钟 ${t.actualSeconds%60} 秒`:''}</p>`,`<button class="btn secondary" data-action="start-focus" data-id="${t.id}">◷ 开始专注</button><button class="btn" data-action="detail-toggle" data-id="${t.id}">${t.status==='done'?'恢复为待办':'标记完成'}</button>`)}
function reschedule(){if(!state.enabled.life||!state.enabled.planner){toast('重新排期需要启用生活与计划 Agent。');return}const t=todayTasks().find(t=>t.status!=='done');if(!t){toast('今天没有需要调整的未完成任务。');return}showModal('给日程一点弹性','模拟建议 · 只调整未完成任务，确认后生效。',`<div class="inline-info">今日精力：${state.energy}<br>${state.energy==='疲惫'?'建议降低今天的负荷，留出休息时间。':'这是一份示例调整，你可以决定是否采用。'}</div><div class="proposal-task"><b>${esc(t.title)}</b><small>原安排：${pretty(t.date)} · ${t.minutes} 分钟</small><small>建议安排：${pretty(addDays(t.date,1))} · 耗时不变</small></div><p class="tiny muted">已完成的任务保留原日期。正式版需额外检查截止时间和次日剩余容量。</p>`,`<button class="btn secondary" data-action="close-modal">保留原计划</button><button class="btn" data-action="apply-reschedule" data-id="${t.id}" data-date="${t.date}">确认调整</button>`)}
const questions=[{q:'使用 useState 更新依赖旧值的计数，哪种写法更合适？',options:['setCount(count + 1)','setCount(prev => prev + 1)','直接修改 count'],answer:1,explain:'函数式更新从待处理的前一个状态计算新值，更适合依赖旧值的更新。'},{q:'useEffect 的清理函数通常用来做什么？',options:['直接渲染页面','释放订阅、计时器等资源','创建新的全局变量'],answer:1,explain:'清理函数释放副作用创建的资源，避免重复订阅或遗留定时器。'},{q:'自定义 Hook 的主要作用是什么？',options:['共享组件之间的状态逻辑','自动共享所有组件的同一份状态','替代所有组件'],answer:0,explain:'自定义 Hook 复用状态逻辑；各次调用的状态通常相互独立。'}];
function quiz(result=null){showModal(result?'每一次反馈，都让理解更清晰':'用三道题，检验一点理解','React 示例测验 · 3 道单选题，每题 1 分。',`<form id="quiz-form">${questions.map((q,i)=>`<div class="quiz-question"><h3>${i+1}. ${q.q}</h3>${q.options.map((o,j)=>`<label class="quiz-option"><input type="radio" name="q${i}" value="${j}" ${result?.answers[i]===j?'checked':''} ${result?'disabled':''} required>${esc(o)}</label>`).join('')}${result?`<div class="answer">${result.answers[i]===q.answer?'✓ 答对了':'正确答案：'+esc(q.options[q.answer])}<br>${q.explain}</div>`:''}</div>`).join('')}<div class="modal-footer">${result?`<span style="margin-right:auto;font-size:20px">${result.score} / 3</span><button type="button" class="btn secondary" data-action="quiz">重新测验</button>${result.score<3?'<button type="button" class="btn" data-action="quiz-task">加入复习任务</button>':'<button type="button" class="btn" data-action="close-modal">完成</button>'}`:'<button class="btn" type="submit">提交并查看反馈</button>'}</div></form>`)}
function quizTask(){if(!state.quiz){toast('先完成一次测验。');return}if(state.quiz.taskId&&state.tasks.some(t=>t.id===state.quiz.taskId)){toast('这次反馈已加入复习任务。');return}const t={id:id(),goal:state.goals.find(g=>g.type==='学习')?.id||'',title:'复习 React Hooks 与副作用薄弱点',date:addDays(TODAY,1),minutes:25,status:'todo',priority:'高',source:'学习 Agent',note:'根据最近一次示例测验反馈，复习答错的概念并动手验证。'};state.tasks.push(t);state.quiz.taskId=t.id;log('学习 Agent 将薄弱点复习加入明日任务');save();render();closeModal(true);toast('已加入明天的复习任务')}
function noteForm(n){showModal(n?'继续打磨你的理解':'写下今天的一点理解','笔记仅保存在当前浏览器。',`<form id="note-form" data-id="${n?.id||''}"><label class="field">笔记标题<input name="title" maxlength="60" required value="${esc(n?.title||'')}" placeholder="今天我理解了…"></label><label class="field">用自己的话写下来<textarea name="body" maxlength="2000" required style="min-height:180px">${esc(n?.body||'')}</textarea></label><div id="form-error" role="alert" class="error"></div><div class="modal-footer"><button class="btn" type="submit">保存笔记</button></div></form>`)}
function habitForm(){showModal('为生活添一个小习惯','从足够小、可以坚持的行动开始。',`<form id="habit-form"><label class="field">习惯名称<input name="name" maxlength="30" required placeholder="例如：每日散步"></label><label class="field">每日目标<input name="target" maxlength="60" required placeholder="例如：晚饭后散步 15 分钟"></label><div id="form-error" role="alert" class="error"></div><div class="modal-footer"><button class="btn" type="submit">添加习惯</button></div></form>`)}
function focus(t){if(focusTimer){toast('已有一段专注正在进行。');return}t=t||todayTasks().find(x=>x.status!=='done')||state.tasks[0];if(!t){toast('先添加一个任务，再开始专注。');return}focusElapsed=0;focusRunning=false;showModal('给当下，一段完整的时间',esc(t.title),`<div class="timer" id="focus-clock">25:00</div><p style="text-align:center" class="tiny">25 分钟专注 · 可随时结束并保存已用时间。</p>`,`<button class="btn secondary" data-action="focus-pause" id="focus-control">开始计时</button><button class="btn" data-action="focus-end" data-id="${t.id}">结束并记录</button>`);focusTimer=setInterval(()=>{if(!focusRunning)return;const now=Date.now();focusElapsed+=Math.max(0,Math.floor((now-lastFocusTick)/1000));lastFocusTick=now;const left=Math.max(0,1500-focusElapsed);if($('#focus-clock'))$('#focus-clock').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left===0){focusRunning=false;$('#focus-control').textContent='已完成';$('#focus-control').disabled=true;toast('本段专注结束，点击结束并记录保存。')}},1000)}
function showFocusLeave(){if(confirm('结束这段专注并保存当前时间？'))document.querySelector('[data-action="focus-end"]')?.click()}
function navigate(p){page=p;location.hash=p;$('#search-results').hidden=true;render();window.scrollTo(0,0)}
function toggleTask(t){t.status=t.status==='done'?'todo':'done';log(`${t.status==='done'?'完成':'恢复'}任务“${t.title}”`);save();render()}
const actions={
 'navigate':b=>navigate(b.dataset.page),'new-goal':newGoal,'close-modal':()=>closeModal(),'save-draft':()=>submitGoal(true),
 'goal-filter':b=>{goalFilter=b.dataset.value;render()},'goal-detail':b=>goalDetail(state.goals.find(g=>g.id===b.dataset.id)),
 'goal-plan':b=>{if(state.runs.some(r=>r.goal===b.dataset.id&&r.status==='待确认'&&!r.applied)){showProposal(state.runs.find(r=>r.goal===b.dataset.id&&r.status==='待确认'&&!r.applied));return}startRun(state.goals.find(g=>g.id===b.dataset.id))},
 'sample-run':()=>{const g=state.goals.find(g=>g.type==='学习');g?startRun(g):newGoal()},'failure-run':()=>{const g=state.goals.find(g=>g.type==='学习');g?startRun(g,true):newGoal()},
 'run-detail':b=>showRun(state.runs.find(r=>r.id===b.dataset.id)),
 'retry-run':b=>{const r=state.runs.find(r=>r.id===b.dataset.id);if(r.status!=='失败')return;r.status='已重试';startRun(state.goals.find(g=>g.id===r.goal))},
 'dismiss-proposal':b=>{const r=state.runs.find(r=>r.id===b.dataset.id);r.status='取消';r.summary='提案未应用，目标保留';const g=state.goals.find(g=>g.id===r.goal);g.status=state.tasks.some(t=>t.goal===g.id)?'进行中':'草稿';save();render();closeModal(true);toast('保留目标，未创建新任务')},
 'apply-proposal':b=>{const r=state.runs.find(r=>r.id===b.dataset.id);if(r.applied)return;r.proposal.forEach(t=>{if(!state.tasks.some(x=>x.id===t.id))state.tasks.push(t)});r.applied=true;r.status='已应用';r.summary='计划已确认，三个步骤加入日程';state.goals.find(g=>g.id===r.goal).status='进行中';log('计划已确认，任务加入日程');save();closeModal(true);navigate('tasks');toast('计划已加入日程，开始你的第一步吧。')},
 'toggle-task':b=>{const t=state.tasks.find(t=>t.id===b.dataset.id);toggleTask(t);if($('#modal').open){const g=state.goals.find(g=>g.id===t.goal);if(g)goalDetail(g)}},
 'task-detail':b=>taskDetail(state.tasks.find(t=>t.id===b.dataset.id)),'detail-toggle':b=>{toggleTask(state.tasks.find(t=>t.id===b.dataset.id));closeModal(true);toast('任务状态已更新')},
 'new-task':newTask,'task-view':b=>{taskView=b.dataset.value;render()},'week':b=>{weekOffset+=Number(b.dataset.value);render()},
 'habit-check':b=>{const key=`${TODAY}:${b.dataset.id}`;state.checks[key]=!state.checks[key];log(`${state.checks[key]?'完成':'撤销'}习惯“${state.habits.find(h=>h.id===b.dataset.id).name}”`);save();render();toast(state.checks[key]?'今天的小习惯，已记录。':'已撤销今天的打卡')},
 'new-habit':habitForm,'energy':b=>{state.energy=b.dataset.value;save();render();toast('精力状态已更新')},'reschedule':reschedule,
 'apply-reschedule':b=>{const t=state.tasks.find(t=>t.id===b.dataset.id);if(t.status==='done'||t.date!==b.dataset.date){toast('任务状态已变化，请重新生成建议。');closeModal(true);return}const g=state.goals.find(g=>g.id===t.goal);if(g&&addDays(t.date,1)>g.deadline){toast('调整后将超出目标截止日期，已保留原计划。');return}t.date=addDays(t.date,1);log(`已将“${t.title}”调整到明天`);save();render();closeModal(true);toast('已按你的确认调整日程')},
 'quiz':()=>quiz(),'quiz-task':quizTask,'new-note':()=>noteForm(),'edit-note':b=>noteForm(state.notes.find(n=>n.id===b.dataset.id)),
 'resource':b=>{const data={hooks:['React Hooks 速记','useState：保存组件状态。\nuseEffect：同步外部系统，使用依赖列表与清理函数管理生命周期。\n闭包：函数捕获创建时的变量环境，注意旧值问题。'],fetch:['动手写一个 useFetch','练习目标：维护 loading、data 与 error。\n用 effect 发起请求；处理异常；使用 AbortController 在清理时取消请求。\n更改地址后，验证组件会重新获取数据。'],loop:['事件循环图解','同步代码先进入调用栈。\n当前任务完成后，清空微任务队列，再处理后续任务。\n练习：比较 Promise.then 与 setTimeout 的输出顺序。']};showModal(data[b.dataset.id][0],'产品内示例资料卡片',`<div class="note">${data[b.dataset.id][1]}</div>`,'<button class="btn" data-action="close-modal">读完了</button>')},
 'agent-toggle':b=>{if(activeRun?.status==='运行中'){toast('请等待当前运行完成后再调整配置。');return}state.enabled[b.dataset.id]=!state.enabled[b.dataset.id];save();render();toast('伙伴配置已保存')},
 'agent-detail':b=>{const a=agents.find(a=>a.id===b.dataset.id);showModal(a.name,a.en,`<div class="inline-info">${a.desc}</div><h3>擅长这些事</h3><p class="tiny" style="margin-top:12px">${a.detail}</p><div class="insight"><h3>协作原则</h3><p>只读取与当前请求相关的上下文，产出可审阅的摘要。任何日程调整都会先让你确认。</p></div>`,'<button class="btn secondary" data-action="close-modal">了解了</button>')},
 'review-period':b=>{reviewPeriod=b.dataset.value;render()},
 'generate-review':()=>{if(!state.enabled.review){toast('请先启用复盘 Agent。');return}const ts=state.tasks.filter(t=>reviewPeriod==='week'?t.date>='2026-10-05'&&t.date<='2026-10-11':t.date===TODAY),done=ts.filter(t=>t.status==='done');state.review={id:id(),title:`${reviewPeriod==='week'?'本周':'今日'}复盘 · ${pretty(TODAY)}`,text:`执行事实：${done.length} / ${ts.length} 个任务已完成，累计专注 ${Math.floor(state.focusSeconds/60)} 分钟。\n生活状态：今天的精力是${state.energy}，完成 ${state.habits.filter(checked).length} 项习惯打卡。\n学习反馈：${state.quiz?`最近测验 ${state.quiz.score}/3 分。`:'尚未进行测验，建议用一次小测检验理解。'}\n下一步建议：${state.energy==='疲惫'?'适当降低负荷，优先休息与重点任务。':'留 25 分钟复习薄弱点，并整理明天的重点。'}\n以上为根据本地记录生成的模拟总结。`,applied:false};log('复盘 Agent 生成了一份模拟复盘');save();render();toast('复盘已生成，可查看并应用建议')},
 'apply-review':()=>{if(!state.review||state.review.applied)return;state.tasks.push({id:id(),title:'复习薄弱点与整理明日计划',goal:state.goals.find(g=>g.type==='学习')?.id||'',date:addDays(TODAY,1),minutes:25,status:'todo',priority:'中',source:'复盘 Agent',note:'来自已确认的复盘建议。'});state.review.applied=true;save();render();toast('复盘建议已加入明日任务')},
 'start-focus':b=>focus(state.tasks.find(t=>t.id===b.dataset.id)),
 'focus-pause':()=>{focusRunning=!focusRunning;lastFocusTick=Date.now();$('#focus-control').textContent=focusRunning?'暂停计时':'继续计时'},
 'focus-end':b=>{clearInterval(focusTimer);focusTimer=null;focusRunning=false;state.focusSeconds+=focusElapsed;const t=state.tasks.find(t=>t.id===b.dataset.id);if(t)t.actualSeconds=(t.actualSeconds||0)+focusElapsed;log(`记录一段专注：${Math.floor(focusElapsed/60)}分${focusElapsed%60}秒`);save();render();closeModal(true);toast(`已记录 ${Math.floor(focusElapsed/60)} 分钟 ${focusElapsed%60} 秒专注`)},
 'reset':()=>showModal('恢复初始原型数据？','将清除当前浏览器中的目标、任务、笔记与打卡记录。','<div class="inline-info">此操作仅重置 CoLife 原型数据，恢复初始示例。</div>','<button class="btn secondary" data-action="close-modal">保留数据</button><button class="btn danger" data-action="confirm-reset">确认重置</button>'),
 'confirm-reset':()=>{clearInterval(runTimer);clearInterval(focusTimer);runTimer=focusTimer=null;activeRun=null;state=seed();goalFilter='全部';taskFilter='all';save();closeModal(true);navigate('today');toast('已恢复初始示例数据')}
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){const fn=actions[b.dataset.action];if(fn)fn(b)}});
document.addEventListener('change',e=>{if(e.target.matches('[data-task]')){const t=state.tasks.find(t=>t.id===e.target.dataset.task);t.status=e.target.value;log(`更新任务状态：${t.title}`);save();render()}if(e.target.id==='energy'){state.energy=e.target.value;save();render();toast('精力状态已更新')}if(e.target.id==='task-filter'){taskFilter=e.target.value;render()}});
document.addEventListener('input',e=>{if(e.target.closest('form')&&$('#modal').open)modalDirty=true});
document.addEventListener('submit',e=>{if(!e.target.closest('#modal'))return;e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='goal-form'){submitGoal();return}if(form.id==='quiz-form'){const answers=questions.map((_,i)=>Number(f.get('q'+i))),score=answers.filter((a,i)=>a===questions[i].answer).length;state.quiz={id:id(),answers,score};save();render();modalDirty=false;quiz(state.quiz);return}if(form.id==='task-form'){const title=f.get('title').trim(),minutes=Number(f.get('minutes'));if(!title||!Number.isInteger(minutes)||minutes<1||minutes>480){$('#form-error').textContent='请输入有效标题与 1–480 的整数分钟。';return}state.tasks.push({id:id(),title,goal:f.get('goal'),date:f.get('date'),minutes,status:'todo',priority:f.get('priority'),source:'手动创建',note:''})}if(form.id==='note-form'){if(!f.get('title').trim()||!f.get('body').trim()){$('#form-error').textContent='标题与正文不能仅包含空格。';return}const n=state.notes.find(n=>n.id===form.dataset.id)||{id:id()};n.title=f.get('title').trim();n.body=f.get('body').trim();if(!form.dataset.id)state.notes.unshift(n)}if(form.id==='habit-form'){if(!f.get('name').trim()||!f.get('target').trim()){$('#form-error').textContent='名称与目标不能仅包含空格。';return}state.habits.push({id:id(),name:f.get('name').trim(),target:f.get('target').trim(),icon:'✧'})}save();modalDirty=false;closeModal(true);render();toast('已保存')});
$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
$('#search').addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase(),box=$('#search-results');if(!q){box.hidden=true;return}const matches=[...state.goals.filter(g=>g.title.toLowerCase().includes(q)).map(g=>({kind:'goal-detail',id:g.id,title:g.title,label:'目标'})),...state.tasks.filter(t=>t.title.toLowerCase().includes(q)).map(t=>({kind:'task-detail',id:t.id,title:t.title,label:'任务'}))];box.innerHTML=matches.slice(0,8).map(r=>`<button data-action="${r.kind}" data-id="${r.id}"><small>${r.label}</small>${esc(r.title)}</button>`).join('')||'<div class="empty">没有找到匹配的目标或任务</div>';box.hidden=false});
document.addEventListener('click',e=>{if(!e.target.closest('.search-results')&&!e.target.closest('.search-wrap'))$('#search-results').hidden=true});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!$('#modal').open&&!e.target.matches('input,textarea,select')){e.preventDefault();$('#search').focus()}if(e.key==='Escape')$('#search-results').hidden=true});
window.addEventListener('hashchange',()=>{const key=location.hash.slice(1);if(pages.some(p=>p[0]===key)){page=key;render()}});
window.addEventListener('beforeunload',e=>{if(modalDirty||focusTimer||activeRun?.status==='运行中'){e.preventDefault();e.returnValue=''}});
// Interrupted simulations have no real background process; restore them as retryable failures.
state.runs.forEach(r=>{if(r.status==='运行中'){r.status='失败';r.summary='上次模拟被中断，可重新发起';const g=state.goals.find(g=>g.id===r.goal);if(g)g.status='草稿'}});
render();save();if(storageWarning)toast('本地数据不可读取，已恢复初始数据。');
